import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    # a[x][l] will become the smallest R among constraints with X=x and L>=l
    a = [[n + 1] * (n + 2) for _ in range(n + 1)]
    p = 2
    for _ in range(m):
        l, r, x = data[p], data[p + 1], data[p + 2]
        p += 3
        if r < a[x][l]:
            a[x][l] = r

    for x in range(1, n + 1):
        best = n + 1
        row = a[x]
        for l in range(x, 0, -1):
            if row[l] < best:
                best = row[l]
            row[l] = best

    # g[l][r] = number of valid orders on [l,r], divided by (r-l+1)!
    g = [[0] * (n + 2) for _ in range(n + 2)]
    for l in range(1, n + 2):
        g[l][l - 1] = 1

    inv = [0] * (n + 1)
    for i in range(1, n + 1):
        inv[i] = pow(i, MOD - 2, MOD)

    for length in range(1, n + 1):
        ilen = inv[length]
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                if a[k][l] > r:
                    total = (total + g[l][k - 1] * g[k + 1][r]) % MOD
            g[l][r] = total * ilen % MOD

    ans = g[1][n]
    for i in range(2, n + 1):
        ans = ans * i % MOD
    print(ans)

if __name__ == '__main__':
    main()

