import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    limit = 100000

    spf = list(range(limit + 1))
    for p in range(2, 317):
        if spf[p] == p:
            for v in range(p * p, limit + 1, p):
                if spf[v] == v:
                    spf[v] = p

    phi = list(range(limit + 1))
    phi[1] = 1
    for p in range(2, limit + 1):
        if spf[p] == p:
            for v in range(p, limit + 1, p):
                phi[v] -= phi[v] // p

    bucket = [0] * (limit + 1)
    divisor_cache = {}
    answer = 0
    weight = 1
    output = []

    for x in a:
        divisors = divisor_cache.get(x)
        if divisors is None:
            z = x
            factors = []
            while z > 1:
                p = spf[z]
                e = 0
                while z % p == 0:
                    z //= p
                    e += 1
                factors.append((p, e))
            divisors = [1]
            for p, e in factors:
                old = divisors[:]
                multiplier = 1
                for _ in range(e):
                    multiplier *= p
                    divisors += [d * multiplier for d in old]
            divisor_cache[x] = divisors

        added = 0
        for d in divisors:
            added += phi[d] * bucket[d]
            q = bucket[d] + weight
            bucket[d] = q if q < MOD else q - MOD

        answer = (2 * answer + added) % MOD
        output.append(str(answer))
        weight = weight * 2 % MOD

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    main()

