from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            if a>b: a,b=b,a
            by[b].append((a,i))
        m1=0; m2=0; who=-1
        base=0
        gain=[0]*len(conflictingPairs)
        for r in range(1,n+1):
            for x,i in by[r]:
                if x>m1:
                    m2=m1; m1=x; who=i
                elif x==m1:
                    m2=m1
                elif x>m2:
                    m2=x
            base += r-m1
            if who>=0 and m1>m2:
                gain[who] += m1-m2
        return base+max(gain)

