import sys

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    try:
        n = next(it)
    except StopIteration:
        return
    m = next(it)
    q = next(it)
    edges = []
    for _ in range(m):
        edges.append((next(it) - 1, next(it) - 1, next(it)))
    queries = []
    closed = set()
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            queries.append((1, e))
            closed.add(e)
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10 ** 30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for k, (a, b, w) in enumerate(edges):
        if k not in closed and w < dist[a][b]:
            dist[a][b] = dist[b][a] = w

    # Initial all-pairs shortest paths, using symmetry.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            row_i = dist[i]
            dik = row_i[k]
            if dik < inf:
                for j in range(i, n):
                    v = dik + row_k[j]
                    if v < row_i[j]:
                        row_i[j] = dist[j][i] = v

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            v = dist[query[1]][query[2]]
            answers.append(str(v if v < inf else -1))
        else:
            a, b, w = edges[query[1]]
            row_a = dist[a][:]
            row_b = dist[b][:]
            col_a = [dist[i][a] for i in range(n)]
            col_b = [dist[i][b] for i in range(n)]
            for i in range(n):
                row_i = dist[i]
                via_a = col_a[i] + w
                via_b = col_b[i] + w
                for j in range(i, n):
                    v = via_a + row_b[j]
                    if v < row_i[j]:
                        row_i[j] = dist[j][i] = v
                    v = via_b + row_a[j]
                    if v < row_i[j]:
                        row_i[j] = dist[j][i] = v

    sys.stdout.write("\n".join(reversed(answers)))

if __name__ == "__main__":
    main()

