import sys
import math


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    z = data[2:]
    machines = [tuple(z[4*i:4*i+4]) for i in range(n)]

    def minimum_cost(w, a, p, b, q):
        if w == 0:
            return 0
        # It is never useful to buy more than ceil(w/a) S machines.
        last = (w + a - 1) // a
        last_positive = (w - 1) // a
        period = b // math.gcd(a, b)
        best = 10**30

        # For each residue modulo period, the cost is linear while the
        # remaining demand is positive, and increases after it vanishes.
        for r in range(min(period, last + 1)):
            candidates = [r]
            if r <= last_positive:
                candidates.append(r + (last_positive - r) // period * period)
            if r <= last:
                candidates.append(r + (last - r + period - 1) // period * period)
            for k in candidates:
                if 0 <= k <= last:
                    rem = max(0, w - a * k)
                    value = p * k + q * ((rem + b - 1) // b)
                    if value < best:
                        best = value
        return best

    def feasible(w):
        total = 0
        for a, p, b, q in machines:
            total += minimum_cost(w, a, p, b, q)
            if total > budget:
                return False
        return True

    upper = max(max(a * budget // p, b * budget // q)
                for a, p, b, q in machines) + 1
    low = 0
    while upper - low > 1:
        mid = (low + upper) // 2
        if feasible(mid):
            low = mid
        else:
            upper = mid
    print(low)


if __name__ == "__main__":
    solve()

