class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        m = min(n, x)
        dp = [0] * (m + 1)
        dp[0] = 1
        for _ in range(n):
            nd = [0] * (m + 1)
            for k in range(m + 1):
                if dp[k]:
                    nd[k] = (nd[k] + dp[k] * k) % MOD
                    if k < m:
                        nd[k + 1] = (nd[k + 1] + dp[k] * (x - k) * y) % MOD
            dp = nd
        return sum(dp) % MOD

