class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 1_000_000_007
        n = len(s)

        # Binomial coefficients for counting suffixes with a given number
        # of set bits.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # If x has m set bits, its first operation produces m.  Thus m
        # must reach 1 in at most k-1 further operations.
        good = [False] * (n + 1)
        for m in range(1, n + 1):
            value = m
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[m] = steps <= k - 1

        answer = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                # Make this bit zero; the prefix is then smaller than s.
                for total in range(1, n + 1):
                    if good[total] and total >= used:
                        need = total - used
                        if need <= remaining:
                            answer = (answer + comb[remaining][need]) % MOD
                used += 1

        return answer

