        for i in range(1,n+1):
            C[i][0] = C[i][i] = 1
            for j in range(1,i):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
        good = [False]*(n+1)
        for m in range(1,n+1):
            x=m
            steps=0
            while x != 1 and steps <= k:
                x=x.bit_count()
                steps += 1
            good[m] = (x == 1 and steps <= k-1)
        ans=0
