            if ch=='1':
                rem=n-i-1
                for m in range(1,n+1):
                    if good[m] and m>=ones:
                        need=m-ones
                        if 0 <= need <= rem:
                            ans=(ans+C[rem][need])%MOD
                ones+=1
        return ans

