import sys, heapq

def main():
    z = sys.stdin.buffer.read().split()
    n = int(z[0])
    rows = [x.decode() for x in z[1:]]
    inf = 10**9
    dist = [inf] * (n * n)
    heap = []
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]

    for i in range(n):
        q = i * n + i
        dist[q] = 0
        heapq.heappush(heap, (0, q))

    for i in range(n):
        for j, ch in enumerate(rows[i]):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[i][c].append(j)
                incoming[j][c].append(i)
                q = i * n + j
                if dist[q] > 1:
                    dist[q] = 1
                    heapq.heappush(heap, (1, q))

    while heap:
        w, state = heapq.heappop(heap)
        if dist[state] != w:
            continue
        x, y = divmod(state, n)
        nw = w + 2
        for c in range(26):
            us = incoming[x][c]
            vs = outgoing[y][c]
            for u in us:
                base = u * n
                for v in vs:
                    q = base + v
                    if nw < dist[q]:
                        dist[q] = nw
                        heapq.heappush(heap, (nw, q))

    ans = []
    for i in range(n):
        ans.append(' '.join(str(-1 if dist[i*n+j] == inf else dist[i*n+j])
                            for j in range(n)))
    sys.stdout.write('\n'.join(ans))

if __name__ == '__main__':
    main()

