import sys
import heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    H = next(it)
    W = next(it)
    X = next(it)
    P = next(it) - 1
    Q = next(it) - 1
    values = [next(it) for _ in range(H * W)]

    start = P * W + Q
    strength = values[start]
    seen = bytearray(H * W)
    seen[start] = 1
    heap = []

    def add(r, c):
        k = r * W + c
        if not seen[k]:
            seen[k] = 1
            heapq.heappush(heap, (values[k], k))

    if P > 0:
        add(P - 1, Q)
    if P + 1 < H:
        add(P + 1, Q)
    if Q > 0:
        add(P, Q - 1)
    if Q + 1 < W:
        add(P, Q + 1)

    while heap and heap[0][0] * X < strength:
        value, k = heapq.heappop(heap)
        strength += value
        r, c = divmod(k, W)
        if r > 0:
            add(r - 1, c)
        if r + 1 < H:
            add(r + 1, c)
        if c > 0:
            add(r, c - 1)
        if c + 1 < W:
            add(r, c + 1)

    print(strength)

if __name__ == '__main__':
    main()

