import sys

s = sys.stdin.readline().strip()
n = len(s)
r = s[::-1]

# Prefix-function table for the reversed string.
pi = [0] * n
j = 0
for i in range(1, n):
    while j and r[i] != r[j]:
        j = pi[j - 1]
    if r[i] == r[j]:
        j += 1
    pi[i] = j

# The final KMP match is the longest palindromic suffix of s.
j = 0
for c in s:
    while j and c != r[j]:
        j = pi[j - 1]
    if c == r[j]:
        j += 1
    if j == n:
        break

sys.stdout.write(s + s[:n - j][::-1])

