import sys

def main():
    a = list(map(int, sys.stdin.buffer.read().split()))
    if not a:
        return
    n, m = a[0], a[1]
    rows = [0] * n
    k = 2
    for _ in range(m):
        u, v = a[k] - 1, a[k + 1] - 1
        k += 2
        rows[u] ^= 1 << v
        rows[v] ^= 1 << u

    pivots = []
    r = 0
    for c in range(n):
        q = -1
        for i in range(r, n):
            if (rows[i] >> c) & 1:
                q = i
                break
        if q < 0:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free:
        x = 1 << f
        for i, p in enumerate(pivots):
            if (rows[i] >> f) & 1:
                x |= 1 << p
        basis.append(x)

    ans = []
    for v in range(n):
        x = 0
        for j, b in enumerate(basis):
            if (b >> v) & 1:
                x |= 1 << j
        if x == 0:
            print("No")
            return
        ans.append(x)
    print("Yes")
    print(*ans)

if __name__ == '__main__':
    main()

