import sys
import bisect


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    s = next(it).decode()

    ones = []
    twos = []
    slash_prefix = [0] * (n + 1)
    for i, ch in enumerate(s, 1):
        if ch == '1':
            ones.append(i)
        elif ch == '2':
            twos.append(i)
        slash_prefix[i] = slash_prefix[i - 1] + (ch == '/')

    no = len(ones)
    nt = len(twos)

    def possible(L, R, before_ones, through_twos, k):
        need_ones = before_ones + k
        if need_ones == 0:
            left = L
        elif need_ones > no:
            return False
        else:
            left = ones[need_ones - 1] + 1
        left = max(left, L)

        allowed_twos = through_twos - k
        if allowed_twos < 0:
            return False
        if allowed_twos >= nt:
            right = R
        else:
            right = twos[allowed_twos] - 1
        right = min(right, R)

        return left <= right and slash_prefix[right] > slash_prefix[left - 1]

    ans = []
    for _ in range(q):
        L = int(next(it))
        R = int(next(it))
        before_ones = bisect.bisect_left(ones, L)
        through_twos = bisect.bisect_right(twos, R)
        ones_in = bisect.bisect_right(ones, R) - before_ones
        twos_in = through_twos - bisect.bisect_left(twos, L)

        lo, hi = 0, min(ones_in, twos_in) + 1
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if possible(L, R, before_ones, through_twos, mid):
                lo = mid
            else:
                hi = mid

        if possible(L, R, before_ones, through_twos, 0):
            ans.append(str(2 * lo + 1))
        else:
            ans.append('0')

    sys.stdout.write('\n'.join(ans))


if __name__ == '__main__':
    main()

