class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))
        N = n * m
        straight = []
        for dr, dc in dirs:
            a = array('H', [0]) * N
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    v = grid[r][c]
                    if v != 1:
                        rr, cc = r + dr, c + dc
                        x = 1
                        if (0 <= rr < n and 0 <= cc < m and
                            grid[rr][cc] != 1 and grid[rr][cc] != v):
