from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1
        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = min(CAP, factorial[i - 1] * i)

        def completions(odd: int, even: int, next_parity: int) -> int:
            remaining = odd + even
            if remaining == 0:
                return 1
            if next_parity == 1:
                required_odd = (remaining + 1) // 2
                required_even = remaining // 2
            else:
                required_even = (remaining + 1) // 2
                required_odd = remaining // 2
            if odd != required_odd or even != required_even:
                return 0
            return min(CAP, factorial[odd] * factorial[even])

        unused = list(range(1, n + 1))
        result = []
        odd = (n + 1) // 2
        even = n // 2
        next_parity = None

        for _ in range(n):
            for index, value in enumerate(unused):
                parity = value & 1
                if next_parity is not None and parity != next_parity:
                    continue
                new_odd = odd - (parity == 1)
                new_even = even - (parity == 0)
                count = completions(new_odd, new_even, 1 - parity)
                if count < k:
                    k -= count
                else:
                    result.append(value)
                    unused.pop(index)
                    odd, even = new_odd, new_even
                    next_parity = 1 - parity
                    break
            else:
                return []
        return result

