from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] < nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        left = [0]
        right = [0]
        total = [0]
        tag = [0]                 # tag is None for a non-uniform node

        def node(a, b, s, t):
            left.append(a)
            right.append(b)
            total.append(s)
            tag.append(t)
            return len(total) - 1

        def update(p, lo, hi, ql, qr, value):
            if ql <= lo and hi <= qr:
                return node(0, 0, (hi - lo + 1) * value, value)
            mid = (lo + hi) // 2
            a, b = left[p], right[p]
            if tag[p] is not None:
                v = tag[p]
                a = node(0, 0, (mid - lo + 1) * v, v)
                b = node(0, 0, (hi - mid) * v, v)
            if ql <= mid:
                a = update(a, lo, mid, ql, qr, value)
            if qr > mid:
                b = update(b, mid + 1, hi, ql, qr, value)
            return node(a, b, total[a] + total[b], None)

        roots = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            roots[i] = update(roots[i + 1], 0, n - 1,
                              i, nxt[i] - 1, nums[i])

        def query(p, lo, hi, ql, qr):
            if ql <= lo and hi <= qr:
                return total[p]
            overlap_lo = max(lo, ql)
            overlap_hi = min(hi, qr)
            if overlap_lo > overlap_hi:
                return 0
            if tag[p] is not None:
                return tag[p] * (overlap_hi - overlap_lo + 1)
            mid = (lo + hi) // 2
            ans = 0
            if ql <= mid:
                ans += query(left[p], lo, mid, ql, qr)
            if qr > mid:
                ans += query(right[p], mid + 1, hi, ql, qr)
            return ans

        prefix = [0]
        for x in nums:
            prefix.append(prefix[-1] + x)

        ans = 0
        r = -1
        for l in range(n):
            if r < l - 1:
                r = l - 1
            while r + 1 < n:
                x = r + 1
                required = query(roots[l], 0, n - 1, l, x) - (prefix[x + 1] - prefix[l])
                if required > k:
                    break
                r = x
            ans += r - l + 1
        return ans

