from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        parts = p.split('*')

        def occurrences(t):
            m = len(t)
            if m == 0:
                return list(range(n + 1))

            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = prefix[j - 1]
                if t[i] == t[j]:
                    j += 1
                prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = prefix[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = prefix[j - 1]
            return result

        first, middle, last = parts
        starts_first = occurrences(first)
        starts_middle = occurrences(middle)
        starts_last = occurrences(last)
        lf, lm, ll = len(first), len(middle), len(last)

        best = n + 1
        for start in starts_first:
            i = bisect_left(starts_middle, start + lf)
            if i == len(starts_middle):
                continue
            middle_start = starts_middle[i]

            j = bisect_left(starts_last, middle_start + lm)
            if j == len(starts_last):
                continue
            end = starts_last[j] + ll
            if end - start < best:
                best = end - start

        return -1 if best == n + 1 else best

