    for start in range(n):
        if potential[start] is not None:
            continue
        potential[start] = 0
        stack = [start]
        component = []

        while stack:
            v = stack.pop()
            component.append(v)
            for w, z in graph[v]:
                expected = potential[v] ^ z
                if potential[w] is None:
                    potential[w] = expected
                    stack.append(w)
                elif potential[w] != expected:
                    print(-1)
                    return

        size = len(component)
        shift = 0
        for bit in range(31):
            ones = sum((potential[v] >> bit) & 1 for v in component)
            if ones > size - ones:
                shift |= 1 << bit
        for v in component:
            answer[v] = potential[v] ^ shift

    print(*answer)

