import sys

def main():
    a = list(map(int, sys.stdin.buffer.read().split()))
    if not a:
        return
    n, W = a[0], a[1]
    best = {}
    p = 2
    for _ in range(n):
        w, v = a[p], a[p + 1]
        p += 2
        if v > best.get(w, 0):
            best[w] = v

    NEG = -10**30
    dp = [0] + [NEG] * W
    for w, v in best.items():
        nd = [NEG] * (W + 1)
        for r in range(w if w <= W else W + 1):
            hull = []
            head = 0
            lim = (W - r) // w
            for j in range(lim + 1):
                idx = r + j * w
                old = dp[idx]
                if old > NEG // 2:
                    line_m = j
                    line_b = old - j * j
                    while len(hull) - head >= 2:
                        m1, b1 = hull[-2]
                        m2, b2 = hull[-1]
                        if (b1 - b2) * (line_m - m2) >= (b2 - line_b) * (m2 - m1):
                            hull.pop()
                        else:
                            break
                    hull.append((line_m, line_b))
                x = 2 * j - v
                while len(hull) - head >= 2:
                    m1, b1 = hull[head]
                    m2, b2 = hull[head + 1]
                    if m1 * x + b1 <= m2 * x + b2:
                        head += 1
                    else:
                        break
                if head < len(hull):
                    m, b = hull[head]
                    nd[idx] = -j * j + j * v + m * x + b
        dp = nd
    print(max(dp))

if __name__ == '__main__':
    main()

