    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        best_a = [0] * n
        best_b = [0] * n
        best_a[0] = energyDrinkA[0]
        best_b[0] = energyDrinkB[0]
        if n > 1:
            best_a[1] = energyDrinkA[0] + energyDrinkA[1]
            best_b[1] = energyDrinkB[0] + energyDrinkB[1]
        for i in range(2, n):
            best_a[i] = energyDrinkA[i] + max(best_a[i - 1], best_b[i - 2])
            best_b[i] = energyDrinkB[i] + max(best_b[i - 1], best_a[i - 2])
        return max(best_a[-1], best_b[-1])

