import sys
from math import isqrt

def main():
    N = int(sys.stdin.buffer.read())
    X = isqrt(N)

    sieve = bytearray(b'\x01') * (X + 1)
    if X >= 0:
        sieve[0] = 0
    if X >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(X) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:X + 1:p] = b'\x00' * (((X - start) // p) + 1)

    primes = [p for p, is_prime in enumerate(sieve) if is_prime]

    eighth_root = isqrt(isqrt(isqrt(N)))
    answer = 0
    for p in primes:
        if p <= eighth_root:
            answer += 1
        else:
            break

    # Count pairs of distinct primes p < q with p*q <= sqrt(N).
    j = len(primes) - 1
    for i, p in enumerate(primes):
        while j > i and p * primes[j] > X:
            j -= 1
        if j <= i:
            break
        answer += j - i

    print(answer)

if __name__ == '__main__':
    main()

