from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(x == 0 for x in nums):
            return 0

        # dp[i] is a bitset of sums achievable at index i using
        # the queries processed so far.
        dp = [1] * n  # sum 0 is initially achievable

        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                dp[i] |= dp[i] << val
                # Sums larger than the required value are irrelevant.
                dp[i] &= (1 << (nums[i] + 1)) - 1

            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return k

        return -1

