import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        prime = [True] * limit
        prime[0] = prime[1] = False
        for p in range(2, 100):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1
        if n == m:
            return n

        digits_count = len(str(n))
        distances = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distances[value]:
                continue
            if value == m:
                return cost

            digits = list(str(value))
            for i, char in enumerate(digits):
                digit = ord(char) - ord('0')
                for next_digit in (digit - 1, digit + 1):
                    if not 0 <= next_digit <= 9:
                        continue
                    if i == 0 and next_digit == 0:
                        continue
                    next_digits = digits.copy()
                    next_digits[i] = chr(ord('0') + next_digit)
                    next_value = int(''.join(next_digits))
                    if prime[next_value]:
                        continue
                    next_cost = cost + next_value
                    if next_cost < distances.get(next_value, 10**18):
                        distances[next_value] = next_cost
                        heapq.heappush(heap, (next_cost, next_value))

        return -1

