class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        def z_array(a):
            m = len(a)
            z = [0] * m
            if m:
                z[0] = m
            left = right = 0
            for k in range(1, m):
                if k <= right:
                    z[k] = min(right - k + 1, z[k - left])
                while k + z[k] < m and a[z[k]] == a[k + z[k]]:
                    z[k] += 1
                if k + z[k] - 1 > right:
                    left, right = k, k + z[k] - 1
            return z

        prefix_z = z_array(nums)
        answer = 0

        # i and j are the two cut positions.
        for i in range(1, n - 1):
