            suffix_z = z_array(nums[i:])
            upper = (n + i) // 2
            # Avoid counting splits already counted by the first condition.
            if first_is_prefix:
                upper = min(upper, 2 * i - 1)
            for j in range(i + 1, upper + 1):
                length = j - i
                if suffix_z[length] >= length:
                    answer += 1

        return answer

