    for i, x in enumerate(a):
        if not selected[i]:
            heapq.heappush(candidates, (-x, i))

        if i % 2 == 0:
            required = (i + 2) // 2
            while count < required:
                while candidates and selected[candidates[0][1]]:
                    heapq.heappop(candidates)

                neg_x, j = heapq.heappop(candidates)
                selected[j] = True
                total += -neg_x
                count += 1

    # The final stack height must have the same parity as N.
    if count % 2 != n % 2:
        removable = min(
            (a[i] for i in range(n) if selected[i] and a[i] <= 0),
            default=None
        )
        if removable is not None:
            total -= removable
            count -= 1
        else:
            # Add the best possible unused element.
            best = None
            current = count
            for i, x in enumerate(a):
                if not selected[i] and i <= 2 * current - 1:
                    if best is None or x > best:
                        best = x
            if best is not None:
                total += best

    print(total)

