class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        reverse = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.append(w)

        candidates = sorted(set(weights))

        def reachable(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                u = stack.pop()
                for v, w in reverse[u]:
                    if w <= limit and not seen[v]:
                        seen[v] = True
                        count += 1
                        stack.append(v)
            return count == n

        if not candidates or not reachable(candidates[-1]):
            return -1

        lo, hi = 0, len(candidates) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if reachable(candidates[mid]):
                hi = mid
            else:
                lo = mid + 1
        return candidates[lo]

