class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**30
        dp = [[INF] * 3 for _ in range(3)]

        for left in range(3):
            for right in range(3):
                if left != right:
                    dp[left][right] = cost[0][left] + cost[n - 1][right]

        for i in range(1, n // 2):
            next_dp = [[INF] * 3 for _ in range(3)]
            for left in range(3):
                for right in range(3):
                    if left == right:
                        continue
                    best_previous = INF
                    for prev_left in range(3):
                        for prev_right in range(3):
                            if prev_left != left and prev_right != right:
                                if dp[prev_left][prev_right] < best_previous:
                                    best_previous = dp[prev_left][prev_right]
                    next_dp[left][right] = (
                        best_previous + cost[i][left] + cost[n - 1 - i][right]
                    )
            dp = next_dp

        return min(min(row) for row in dp)

