class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base = s.count('1')
        t = '1' + s + '1'

        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        # Keep the largest few zero runs, so that one can be selected
        # even when the largest one borders the one-run being removed.
        largest_zero = sorted(
            ((length, index) for index, (kind, length) in enumerate(runs)
             if kind == '0'),
            reverse=True
        )[:3]

        best_gain = 0
        for k, (kind, one_length) in enumerate(runs):
            if (kind != '1' or k == 0 or k + 1 == len(runs)
                    or runs[k - 1][0] != '0'
                    or runs[k + 1][0] != '0'):
                continue

            left = runs[k - 1][1]
            right = runs[k + 1][1]

            # The removal joins the two neighboring zero blocks; filling
            # that joined block gains exactly left + right active sections.
            best_gain = max(best_gain, left + right)

            # Alternatively, fill any other already-surrounded zero block.
            for zero_length, zero_index in largest_zero:
                if zero_index != k - 1 and zero_index != k + 1:
                    best_gain = max(best_gain, zero_length - one_length)
                    break

        return base + max(0, best_gain)

