class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base=s.count('1')
        t='1'+s+'1'
        runs=[]
        i=0
        while i<len(t):
            j=i
            while j<len(t) and t[j]==t[i]: j+=1
            runs.append((t[i],j-i))
            i=j
        zeros=[(ln,k) for k,(c,ln) in enumerate(runs) if c=='0']
        top=sorted(zeros, reverse=True)[:3]
        best=0
        for k,(c,a) in enumerate(runs):
            if c=='1' and k>0 and k+1<len(runs) and runs[k-1][0]=='0' and runs[k+1][0]=='0':
                best=max(best,runs[k-1][1]+runs[k+1][1])
                for z,zi in top:
                    if zi not in (k-1,k+1):
                        best=max(best,z-a); break
        return base+max(0,best)

